import os
import glob

# Search recursive for any files mentioning 0aa96415 or result data
def find_files_with_content(search_string, base='.'):
    results = []
    for root, dirs, files in os.walk(base):
        for fname in files:
            try:
                with open(os.path.join(root, fname)) as f:
                    content = f.read()
                    if search_string in content:
                        results.append(os.path.join(root, fname))
            except:
                pass
    return results

